def initialize_weights(model, config):
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            # Centered exact standardized fan-in initialization
            nn.init.normal_(m.weight, 0, 1.0)
            fan_in = m.weight.shape[1] * m.weight.shape[2] * m.weight.shape[3]
            gain = math.sqrt(2.0)
            std_target = gain / math.sqrt(fan_in)

            with torch.no_grad():
                mean = m.weight.mean(dim=(1, 2, 3), keepdim=True)
                var = m.weight.var(dim=(1, 2, 3), unbiased=False, keepdim=True)
                m.weight.sub_(mean).div_(torch.sqrt(var) + 1e-5).mul_(std_target)

            if m.bias is not None:
                nn.init.zeros_(m.bias)

        elif isinstance(m, nn.BatchNorm2d):
            # Base initialization for BN
            nn.init.ones_(m.weight)
            nn.init.zeros_(m.bias)

        elif isinstance(m, nn.Linear):
            nn.init.normal_(m.weight, 0, 1.0)
            fan_in = m.weight.shape[1]
            gain = 1.0 if m.out_features == config['num_classes'] else math.sqrt(2.0)
            std_target = gain / math.sqrt(fan_in)

            with torch.no_grad():
                mean = m.weight.mean(dim=1, keepdim=True)
                var = m.weight.var(dim=1, unbiased=False, keepdim=True)
                m.weight.sub_(mean).div_(torch.sqrt(var) + 1e-5).mul_(std_target)

            if m.bias is not None:
                nn.init.zeros_(m.bias)

    # Architecture-specific adjustments
    for m in model.modules():
        if type(m).__name__ == 'BasicBlock':
            # Zero-init last BN in residual branch
            nn.init.zeros_(m.bn2.weight)
            # BN1 is followed by ReLU, we can boost variance recovery
            nn.init.constant_(m.bn1.weight, math.sqrt(2.0))

        elif type(m).__name__ == 'VGG':
            # In VGG all BNs are followed by ReLU. Perfect variance preservation!
            for sm in m.modules():
                if isinstance(sm, nn.BatchNorm2d):
                    nn.init.constant_(sm.weight, math.sqrt(2.0))

        elif type(m).__name__ == 'InvertedResidual':
            # Zero-init last BN if residual
            if m.use_res and isinstance(m.conv[-1], nn.BatchNorm2d):
                nn.init.zeros_(m.conv[-1].weight)
            # Boost intermediate BNs followed by ReLU6
            if len(m.conv) > 3: # expand ratio > 1, has 3 BNs
                nn.init.constant_(m.conv[1].weight, math.sqrt(2.0))
                nn.init.constant_(m.conv[4].weight, math.sqrt(2.0))
            else: # expand ratio == 1, has 2 BNs
                nn.init.constant_(m.conv[1].weight, math.sqrt(2.0))

def initialize_weights(model, config):
    for m in model.modules():
        if isinstance(m, nn.Conv2d):
            if m.groups == m.in_channels and m.in_channels > 1:
                # Depthwise: normal initialization to avoid orthogonal() issues with shape [C, 1]
                nn.init.normal_(m.weight, 0, 1.0)
            else:
                # Standard Conv: Orthogonal initialization
                nn.init.orthogonal_(m.weight, gain=1.0)

            # Scaled Weight Standardization (Fan-in mode to balance variance)
            with torch.no_grad():
                mean = m.weight.mean(dim=(1, 2, 3), keepdim=True)
                var = m.weight.var(dim=(1, 2, 3), unbiased=False, keepdim=True)

                fan_in = m.weight[0].numel()
                gain = math.sqrt(2.0)
                std_target = gain / math.sqrt(fan_in)

                m.weight.sub_(mean).div_(torch.sqrt(var) + 1e-5).mul_(std_target)

            if m.bias is not None:
                nn.init.zeros_(m.bias)

        elif isinstance(m, nn.BatchNorm2d):
            nn.init.ones_(m.weight)
            nn.init.zeros_(m.bias)

        elif isinstance(m, nn.Linear):
            nn.init.orthogonal_(m.weight, gain=1.0)
            with torch.no_grad():
                mean = m.weight.mean(dim=1, keepdim=True)
                var = m.weight.var(dim=1, unbiased=False, keepdim=True)

                fan_in = m.weight.shape[1]
                gain = 1.0 if m.out_features == config['num_classes'] else math.sqrt(2.0)
                std_target = gain / math.sqrt(fan_in)

                m.weight.sub_(mean).div_(torch.sqrt(var) + 1e-5).mul_(std_target)

            if m.bias is not None:
                nn.init.zeros_(m.bias)

    # Architecture-specific adjustments
    for m in model.modules():
        if type(m).__name__ == 'BasicBlock':
            # Zero-init the last BN in residual branches so blocks start as identity
            nn.init.zeros_(m.bn2.weight)
        elif type(m).__name__ == 'InvertedResidual':
            # Zero-init last BN in inverted residual branch if it adds to shortcut
            if m.use_res and isinstance(m.conv[-1], nn.BatchNorm2d):
                nn.init.zeros_(m.conv[-1].weight)
